using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> A(n), B(n);
    for (int i = 0; i < n; i++) cin >> A[i];
    for (int i = 0; i < n; i++) cin >> B[i];

    long long extra_needed = 0;
    int mandatory = 0;
    vector<long long> slack; // slack for passing exams

    for (int i = 0; i < n; i++) {
        if (A[i] < B[i]) {
            mandatory++;
            extra_needed += B[i] - A[i];
        } else {
            slack.push_back(A[i] - B[i]);
        }
    }

    if (extra_needed == 0) {
        cout << 0 << endl;
        return 0;
    }

    // Sort slack descending to greedily pick largest first
    sort(slack.begin(), slack.end(), greater<long long>());

    long long covered = 0;
    int changes = 0;
    bool possible = false;
    for (int i = 0; i < (int)slack.size(); i++) {
        covered += slack[i];
        changes++;
        if (covered >= extra_needed) {
            possible = true;
            break;
        }
    }

    if (!possible) {
        cout << -1 << endl;
    } else {
        cout << mandatory + changes << endl;
    }

    return 0;
