import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N];
        long[] B = new long[N];

        long sumA = 0;
        long sumB = 0;
        for (int i = 0; i < N; i++) {
            A[i] = fs.nextLong();
            sumA += A[i];
        }
        for (int i = 0; i < N; i++) {
            B[i] = fs.nextLong();
            sumB += B[i];
        }

        if (sumA < sumB) {
            System.out.println(-1);
            return;
        }

        long deficit = 0;
        int needChange = 0;
        ArrayList<Long> surplusList = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            if (A[i] < B[i]) {
                deficit += (B[i] - A[i]);
                needChange++;
            } else if (A[i] > B[i]) {
                surplusList.add(A[i] - B[i]);
            }
        }

        if (deficit == 0) {
            System.out.println(0);
            return;
        }

        surplusList.sort(Collections.reverseOrder());

        long collected = 0;
        int extraChange = 0;
        for (long s : surplusList) {
            collected += s;
            extraChange++;
            if (collected >= deficit) break;
        }

        System.out.println(needChange + extraChange);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

