#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);

    long long sumA = 0, sumB = 0;
    long long deficit = 0;
    int *A = malloc(N * sizeof(int));
    int *B = malloc(N * sizeof(int));

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        sumA += A[i];
    }
    for (int i = 0; i < N; i++) {
        scanf("%d", &B[i]);
        sumB += B[i];
        if (A[i] < B[i]) {
            deficit += B[i] - A[i];
        }
    }

    if (sumA < sumB) {
        printf("-1\n");
        free(A);
        free(B);
        return 0;
    }

    // Calculate surplus
    long long surplus = 0;
    for (int i = 0; i < N; i++) {
        if (A[i] > B[i]) {
            surplus += A[i] - B[i];
        }
    }

    if (surplus >= deficit) {
        // Count how many elements need to change
        int changes = 0;
        for (int i = 0; i < N; i++) {
            if (A[i] < B[i]) {
                changes++;
            }
        }
        // Also count elements that have surplus but may need to give some away
        // Actually, we need to count all elements that are not already sufficient
        // The minimal changes are: elements with deficit + some with surplus if needed
        // But since surplus >= deficit, we can just count deficit elements
        // However, if we need to take from surplus elements, those also count as changes
        // We need to find the minimal number of elements to decrease
        // Sort surpluses and take from smallest surpluses first to minimize changes
        long long *surplusArr = malloc(N * sizeof(long long));
        int surplusCount = 0;
        for (int i = 0; i < N; i++) {
            if (A[i] > B[i]) {
                surplusArr[surplusCount++] = A[i] - B[i];
            }
        }

        // Sort surpluses in ascending order
        for (int i = 0; i < surplusCount - 1; i++) {
            for (int j = 0; j < surplusCount - i - 1; j++) {
                if (surplusArr[j] > surplusArr[j+1]) {
                    long long temp = surplusArr[j];
                    surplusArr[j] = surplusArr[j+1];
                    surplusArr[j+1] = temp;
                }
            }
        }

        long long needed = deficit;
        int surplusChanges = 0;
        for (int i = 0; i < surplusCount && needed > 0; i++) {
            needed -= surplusArr[i];
            surplusChanges++;
        }

        changes += surplusChanges;
        printf("%d\n", changes);

        free(surplusArr);
    } else {
        printf("-1\n");
    }

    free(A);
    free(B);
    return 0;
}

